require __DIR__.'/../lib/auth_admin.php';if(admin_user())redirect('/admin/dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!rate_limit_check('admin'))$error='Terlalu banyak percobaan.';else{$code=strtoupper(trim((string)($_POST['code']??'')));$s=db()->prepare('SELECT * FROM admins WHERE code_lookup=? AND active=1 LIMIT 1');$s->execute([lookup_token($code)]);$u=$s->fetch();$ok=$u&&password_verify($code,$u['code_hash']);log_auth_attempt('admin',(bool)$ok);if($ok){session_regenerate_id(true);$_SESSION['admin_id']=$u['id'];redirect('/admin/dashboard.php');}else$error='Kode admin tidak valid.';}}
